// ---- mods bundled with the game (zip files shipped as included files) ----
function mod_fs_bundled_install(url) {
    mod_fs_init();
    __mfs.status = 1; __mfs.message = "";
    (async function () {
        try {
            var bases = [String(url), "./" + String(url).replace(/^[.\/]+/, ""), "/" + String(url).replace(/^[.\/]+/, "")];
            var blob = null;
            for (var i = 0; i < bases.length && !blob; i++) {
                try {
                    var r = await fetch(bases[i]);
                    if (r.ok) blob = await r.blob();
                } catch (x) {}
            }
            if (!blob) throw new Error("Bundled mod file not found");
            var z = await __mfsReadZip(blob);
            var names = await __mfsInstall(z);
            __mfs.message = names.join(", ") + " (" + __mfs.report + ")";
            __mfs.status = 2;
        } catch (e) {
            __mfs.message = (e && e.message) ? e.message : "Install failed";
            __mfs.status = -1;
        }
    })();
    return 1;
}


// ---- save backup export / import (browser download + file picker) ----
var __fbImp = { status: 0, content: "" };
function fb_file_export(name, content) {
    var blob = new Blob([String(content)], { type: "application/json" });
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = String(name);
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 5000);
    return 1;
}
function fb_file_import_start() {
    __fbImp.status = 0; __fbImp.content = "";
    var input = document.createElement("input");
    input.type = "file"; input.accept = ".json,application/json,text/plain";
    input.onchange = function (e) {
        var f = e.target.files && e.target.files[0];
        if (!f) { __fbImp.status = -1; return; }
        var r = new FileReader();
        r.onload = function (ev) { __fbImp.content = String(ev.target.result); __fbImp.status = 1; };
        r.onerror = function () { __fbImp.status = -1; };
        r.readAsText(f, "UTF-8");
    };
    input.addEventListener("cancel", function () { if (__fbImp.status === 0) __fbImp.status = -1; });
    input.click();
    return 1;
}
function fb_file_import_status() { return __fbImp.status; }
function fb_file_import_content() { return __fbImp.content; }


// dev autotest hook: ?fb_at=... in the page URL (empty string when absent)
function mod_fs_url_param(name) {
    try { return new URLSearchParams(window.location.search).get(String(name)) || ""; } catch (x) { return ""; }
}

// Trailer recorder: captures the game canvas + game audio with MediaRecorder and downloads a .webm.
// Audio is tapped by wrapping AudioNode.connect so anything routed to the speakers is also routed to a recorder stream.
var __trec = { rec: null, chunks: [], dests: [], started: false };

(function () {
    try {
        var origConnect = AudioNode.prototype.connect;
        AudioNode.prototype.connect = function (dest) {
            var r = origConnect.apply(this, arguments);
            try {
                if (dest && typeof AudioDestinationNode !== "undefined" && dest instanceof AudioDestinationNode) {
                    var ctx = dest.context;
                    if (!ctx.__trecDest) {
                        ctx.__trecDest = ctx.createMediaStreamDestination();
                        __trec.dests.push(ctx.__trecDest);
                    }
                    if (!this.__trecTapped) {
                        origConnect.call(this, ctx.__trecDest);
                        this.__trecTapped = true;
                    }
                }
            } catch (e) {}
            return r;
        };
    } catch (e) {}
})();

function trailer_rec_start() {
    try {
        if (__trec.rec) return 0;
        var canvas = document.getElementById("canvas") || document.querySelector("canvas");
        if (!canvas || !canvas.captureStream) return 0;
        var tracks = canvas.captureStream(30).getVideoTracks();
        var hasAudio = false;
        for (var i = 0; i < __trec.dests.length; i++) {
            var at = __trec.dests[i].stream.getAudioTracks();
            for (var j = 0; j < at.length; j++) { tracks.push(at[j]); hasAudio = true; }
        }
        var stream = new MediaStream(tracks);
        var mime = "video/webm;codecs=vp9,opus";
        if (!MediaRecorder.isTypeSupported(mime)) mime = "video/webm;codecs=vp8,opus";
        if (!MediaRecorder.isTypeSupported(mime)) mime = "video/webm";
        __trec.chunks = [];
        __trec.rec = new MediaRecorder(stream, { mimeType: mime, videoBitsPerSecond: 8000000 });
        __trec.rec.ondataavailable = function (e) { if (e.data && e.data.size) __trec.chunks.push(e.data); };
        __trec.rec.onstop = function () {
            var blob = new Blob(__trec.chunks, { type: "video/webm" });
            var a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = "frickbears3_trailer.webm";
            document.body.appendChild(a);
            a.click();
            setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 4000);
            __trec.rec = null;
        };
        __trec.rec.onerror = function (e) { console.log("trailer rec error", e); };
        __trec.rec.addEventListener("stop", function () { console.log("trailer rec stopped, chunks=" + __trec.chunks.length); });
        __trec.rec.start(500);
        return hasAudio ? 2 : 1; // 2 = video+audio, 1 = video only
    } catch (e) { return 0; }
}

function trailer_rec_stop() {
    try { if (__trec.rec && __trec.rec.state !== "inactive") { __trec.rec.stop(); return 1; } } catch (e) {}
    return 0;
}

// Download everything recorded so far (works while recording and after it ended), without stopping the recorder.
function trailer_rec_save() {
    try {
        if (!__trec.chunks.length) return 0;
        var blob = new Blob(__trec.chunks, { type: "video/webm" });
        var a = document.createElement("a");
        a.href = URL.createObjectURL(blob);
        a.download = "frickbears3_trailer_export.webm";
        document.body.appendChild(a);
        a.click();
        setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 4000);
        return 1;
    } catch (e) { return 0; }
}


